COPY compliance.obligations (id, code, framework, article, title, description, scope, created_at) FROM stdin;
0b50acc8-4e58-45c6-89d3-60b189fe4fed	AI-ACT-ART9	AI_ACT	Art. 9	Sistema de gestión de riesgos	Establecer, implementar, documentar y mantener un sistema de gestión de riesgos para el ciclo de vida del sistema de IA.	high_risk	2026-05-05 21:24:56.278426+00
ca83f30c-87dd-4f66-964f-182af5a22f1a	AI-ACT-ART10	AI_ACT	Art. 10	Datos y gobernanza de datos	Los datos de entrenamiento, validación y prueba deben cumplir criterios de calidad, ser pertinentes y libres de sesgos inapropiados.	high_risk	2026-05-05 21:24:56.278426+00
f115f600-fc91-4a1a-8f8c-3e0a955d6c9b	AI-ACT-ART11	AI_ACT	Art. 11	Documentación técnica	Elaborar y mantener documentación técnica completa del sistema de IA antes de su puesta en el mercado.	high_risk	2026-05-05 21:24:56.278426+00
8cbad839-5038-491c-a36c-aa270399356b	AI-ACT-ART12	AI_ACT	Art. 12	Registro de eventos (logs)	Los sistemas de IA de alto riesgo deben generar logs automáticos que permitan trazabilidad a lo largo de su ciclo de vida.	high_risk	2026-05-05 21:24:56.278426+00
b8ddd966-7c71-468f-ba68-44a35d2fd6b7	AI-ACT-ART13	AI_ACT	Art. 13	Transparencia e información	Los sistemas de IA deben ser suficientemente transparentes para que los usuarios puedan interpretar las salidas y usarlas apropiadamente.	high_risk	2026-05-05 21:24:56.278426+00
33803f22-e9d6-4c36-8287-28813deddc6b	AI-ACT-ART14	AI_ACT	Art. 14	Supervisión humana	Los sistemas de IA deben incorporar medidas que permitan supervisión humana efectiva durante su uso.	high_risk	2026-05-05 21:24:56.278426+00
f1f39517-a009-4068-80a1-db709b6d103e	AI-ACT-ART15	AI_ACT	Art. 15	Exactitud, robustez y ciberseguridad	Los sistemas de IA deben alcanzar un nivel apropiado de exactitud, robustez y resiliencia frente a errores y ataques.	high_risk	2026-05-05 21:24:56.278426+00
f1c64737-c246-43d9-9b9a-1d65d195e1f0	AI-ACT-ART16	AI_ACT	Art. 16	Obligaciones de los proveedores	El proveedor debe garantizar conformidad, registrar el sistema, disponer de sistema de calidad y notificar incidentes graves.	high_risk	2026-05-05 21:24:56.278426+00
ac9a3b00-9499-4c93-aa5d-a197bd4c0844	AI-ACT-ART72	AI_ACT	Art. 72	Evaluación de impacto de derechos fundamentales (FRIA)	Antes del despliegue, los desplegadores de sistemas de alto riesgo en ámbitos públicos deben realizar una FRIA.	high_risk	2026-05-05 21:24:56.278426+00
2e15b484-f704-4133-bd42-0030276a3750	ISO42001-A61	ISO_42001	A.6.1	Objetivos del sistema de gestión de IA	Establecer objetivos medibles para el SGAI alineados con la política de IA de la organización.	\N	2026-05-05 21:24:56.278426+00
d0e8858b-5d11-42cb-9ad6-3cce5bdc07b8	ISO42001-A62	ISO_42001	A.6.2	Evaluación de impacto de la IA	Realizar evaluaciones de impacto de los sistemas de IA sobre individuos, grupos y sociedad.	\N	2026-05-05 21:24:56.278426+00
